use std::rc::Rc;

fn try_increment(num: &mut Rc<i32>, share: bool) -> bool {
    let _other = if share { Some(⟦slot2⟧) } else { None };
    if let Some(inner) = ⟦slot1⟧ {
        *inner += 1;
        true
    } else {
        false
    }
}

fn main() {
    let mut num = Rc::new(42);
    println!("{}", try_increment(&mut num, false));
}

tests:
#[test]
fn updates_only_when_unique() {
    let mut num = Rc::new(42);
    assert!(try_increment(&mut num, false));
    assert_eq!(*num, 43);
    assert!(!try_increment(&mut num, true));
    assert_eq!(*num, 43);
}
